import Foundation

/// Public, self-written sentences and their 256-dimensional document vectors, for `Vauta mlx-selftest --model` and the
/// model-gated parity tests.
///
/// The vectors were made with Hugging Face's reference stack (sentence-transformers, fp32 on CPU, no Vauta code) by
/// `tools/search-model/make-goldens.py` on the pinned revision, with the versions in `requirements-goldens.txt`. Vauta's own fp32
/// encoder matched them at cosine 1.00000 on all eight sentences (2026-10-12). Regenerate them only when the pinned revision changes.
enum SearchModelGoldens {
    /// Whether `vectorsBase64` comes from Hugging Face's reference run (see above). `mlx-selftest --model` says which kind it used.
    static let reference = true

    static let strings: [String] = [
        "The quarterly budget review is scheduled for Thursday afternoon.",
        "Hemos acordado aplazar el lanzamiento hasta mediados de noviembre.",
        "Wer übernimmt die Abstimmung mit dem Lieferanten bis Freitag?",
        "Nous avons décidé de réduire les coûts de transport de dix pour cent.",
        "La riunione ha approvato il nuovo piano di assunzioni per il secondo semestre.",
        "O contrato com o fornecedor foi renovado por mais doze meses.",
        "会議では来月の販売目標について話し合いました。",
        "Invoice INV-2026-0417 was paid on the second of March.",
    ]

    /// Float32 little-endian, `strings.count * 256` values, base64.
    static let vectorsBase64 = ""

    static var vectors: [[Float]]? {
        guard let data = Data(base64Encoded: vectorsBase64), data.count == strings.count * 256 * 4 else { return nil }
        let floats = data.withUnsafeBytes { Array($0.bindMemory(to: Float.self)) }
        return (0..<strings.count).map { Array(floats[$0 * 256..<($0 + 1) * 256]) }
    }

    static func cosine(_ a: [Float], _ b: [Float]) -> Float {
        guard a.count == b.count, !a.isEmpty else { return 0 }
        var dot: Float = 0, na: Float = 0, nb: Float = 0
        for i in 0..<a.count { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i] }
        return na > 0 && nb > 0 ? dot / (na.squareRoot() * nb.squareRoot()) : 0
    }
}
